import{_ as t,o as r,c as o,a3 as a}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Misc Projects","description":"","frontmatter":{},"headers":[],"relativePath":"en/projects-diverse/index.md","filePath":"en/projects-diverse/index.md","lastUpdated":1793123188000}'),s={name:"en/projects-diverse/index.md"};function i(n,e,l,c,p,u){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="misc-projects" tabindex="-1">Misc Projects <a class="header-anchor" href="#misc-projects" aria-label="Permalink to &quot;Misc Projects&quot;">​</a></h1><p>This page collects additional UGSo open-source projects that do not directly belong to the C# tools or MQTT apps.</p><h2 id="ultimate-timer" tabindex="-1">Ultimate Timer <a class="header-anchor" href="#ultimate-timer" aria-label="Permalink to &quot;Ultimate Timer&quot;">​</a></h2><p><strong>Ultimate Timer</strong></p><p>A Home Assistant automation blueprint for reusable timers with stable STOP logic, persistent DONE status, multi-instance support and optional MQTT mode.</p><ul><li><a href="/en/projects/ultimate-timer/">Open the Ultimate Timer documentation</a></li><li><a href="https://github.com/rockbaer2007/ha-ultimate-timer-blueprint" target="_blank" rel="noreferrer">Open the blueprint on GitHub</a></li></ul><h2 id="home-assistant-blueprints" tabindex="-1">Home Assistant Blueprints <a class="header-anchor" href="#home-assistant-blueprints" aria-label="Permalink to &quot;Home Assistant Blueprints&quot;">​</a></h2><p><strong>Home Assistant Blueprints</strong></p><p>A small collection of custom Home Assistant blueprints for linking switches, target groups and emergency-off style automations. It includes blueprints for one source with up to six targets, one source with a freely selectable target group and an emergency-off automation that turns selected targets off when the source changes from <code>on</code> to <code>off</code>.</p><ul><li><p>Link 1 to 6: One source switches up to six targets on and off in sync.</p></li><li><p>Link source to target group: One source switches selected entities, devices or areas.</p></li><li><p>Emergency-off source OFF to target group OFF: When the source changes from <code>on</code> to <code>off</code>, the selected targets are turned off.</p></li><li><p>The GitHub README includes direct Home Assistant import buttons for all included blueprints.</p></li><li><p><a href="https://github.com/rockbaer2007/homeassistant-blueprints" target="_blank" rel="noreferrer">Open the blueprints on GitHub</a></p></li></ul><h2 id="more-project-areas" tabindex="-1">More Project Areas <a class="header-anchor" href="#more-project-areas" aria-label="Permalink to &quot;More Project Areas&quot;">​</a></h2><ul><li><a href="/en/projects/">Open C# Projects</a></li><li><a href="/en/projects-mqtt/">Open MQTT Projects</a></li><li><a href="/en/projects/atlas/">Open ATLAS</a></li></ul>',12)])])}const h=t(s,[["render",i]]);export{m as __pageData,h as default};
